/**
 * 工具相关数据模型
 * 包含图片工具和文字工具的数据结构
 */
import { BaseResponseData } from './base-models';

/**
 * 工具基础信息
 */
export class ToolInfo extends BaseResponseData {
    id!: number;
    title!: string;
    description?: string;
    tool_type!: string;
    prompt!: string;
    config?: Record<string, any>;
    creator_id!: number;
    created_at!: string;
    updated_at!: string;
}

/**
 * 工具列表响应
 */
export class ToolListResponse extends BaseResponseData {
    list!: ToolInfo[];
    total!: number;
    has_more!: boolean;
    cursor?: number;
}

/**
 * 工具详情响应
 */
export class ToolDetailResponse extends BaseResponseData {
    tool!: ToolInfo;
}

/**
 * 工具删除响应
 */
export class ToolDeleteResponse extends BaseResponseData {
    success!: boolean;
    message?: string;
}

/**
 * 工具使用响应
 */
export class ToolUseResponse extends BaseResponseData {
    message_id!: number;
    session_id!: string;
    content!: string;
    images?: string[];
    created_at!: string;
}

/**
 * 工具会话信息
 */
export class ToolSessionInfo extends BaseResponseData {
    id!: string; // 用于分页cursor，通常与session_id保持一致
    session_id!: string;
    tool_id!: number;
    title!: string;
    created_at!: string;
    updated_at!: string;
    message_count!: number;
}

/**
 * 工具会话列表响应
 */
export class ToolSessionListResponse extends BaseResponseData {
    list!: ToolSessionInfo[];
    total!: number;
    has_more!: boolean;
    cursor?: number;
}

/**
 * 工具消息信息
 */
export class ToolMessageInfo extends BaseResponseData {
    id!: number;
    session_id!: string;
    role!: 'user' | 'assistant';
    content!: string;
    images?: string[];
    created_at!: string;
    /** 搜索引用链接列表，仅当使用搜索功能时有值 */
    search_citations?: string[];
}

/**
 * 工具消息列表响应
 */
export class ToolMessageListResponse extends BaseResponseData {
    list!: ToolMessageInfo[];
    total!: number;
    has_more!: boolean;
    cursor?: number;
}

/**
 * 媒体上传响应
 */
export class MediaUploadResponse extends BaseResponseData {
    upload_id!: number;
    upload_url!: string;
    file_url!: string;
    needs_upload!: boolean;
}

/**
 * 媒体上传确认响应
 */
export class MediaUploadConfirmResponse extends BaseResponseData {
    file_url!: string;
    success!: boolean;
}

/**
 * 工具列表请求参数
 */
export interface ToolListParams {
    tool_type?: string;
    page_size?: number;
    cursor?: number;
}

/**
 * 工具使用请求参数
 */
export interface ToolUseParams {
    tool_id: number;
    content?: string;
    images?: string[];
    image_ids?: string[];
    session_id?: string;
    /** 使用的AI模型（必填） */
    model: string;
    /** 是否启用实时搜索功能 */
    enable_search?: boolean | null;
}

/**
 * 工具创建请求参数
 */
export interface ToolCreateParams {
    title: string;
    description?: string;
    prompt: string;
    config?: Record<string, any>;
}

/**
 * 工具会话列表请求参数
 */
export interface ToolSessionListParams {
    tool_id: number;
    page_size?: number;
    cursor?: number;
    model?: string;
}

/**
 * 工具消息列表请求参数
 */
export interface ToolMessageListParams {
    session_id: string;
    page_size?: number;
    cursor?: number;
}

/**
 * 工具会话删除请求参数
 */
export interface ToolSessionDeleteParams {
    /** 会话ID */
    id: string;
}

/**
 * 工具会话删除响应信息
 */
export class ToolSessionDeleteResponseInfo extends BaseResponseData {
    /** 操作成功标识 */
    success: boolean;
    /** 删除的会话ID */
    session_id?: string;
    /** 操作消息 */
    message?: string;
}

/**
 * 媒体上传准备请求参数
 */
export interface MediaUploadPrepareParams {
    md5_hash: string;
    file_ext: string;
    file_size: number;
    content_type: string;
    usage_scene: number;
    file_type: number;
    width?: number;
    height?: number;
}

/**
 * 媒体上传确认请求参数
 */
export interface MediaUploadConfirmParams {
    upload_id: number;
}

/**
 * 流式消息数据
 */
export interface StreamMessageData {
    content: string;
    full_content?: string;
    is_text?: boolean;
    parse_error?: boolean;
}

/**
 * 流式消息结束数据
 */
export interface StreamEndData {
    content: string;
}

/**
 * 流式消息回调函数类型
 */
export type StreamMessageCallback = (data: StreamMessageData) => void;

/**
 * 流式错误回调函数类型
 */
export type StreamErrorCallback = (error: Error) => void;

/**
 * 流式结束回调函数类型
 */
export type StreamEndCallback = (data: StreamEndData) => void;

/**
 * 流式控制器
 */
export interface StreamController {
    close: () => void;
}
